function getAllIndexes(arr, val) {
    var indexes = [], i;
    for(i = 0; i < arr.length; i++)
        if (arr[i] === val)
            indexes.push(i);
    return indexes;
}

var behaviorType = ["gentle","wary","distrustful","amicable","aloof","watchful","friendly","curious","territorial"];
var behaviorString = ["They are cautious but friendly towards humans.","They are quick to respond to perceived threats.","They dislike humans in their territory and will try to stay away if possible.","They are comfortable around humans and will not give them much trouble.","They do not react much to the presence of humans.","They dislike humans in their territory, but will not attack unless provoked.","They like humans and may even help them out if they need aid.","They are unafraid of humans and may approach travelers to investigate them.","They dislike humans in their territory and will act aggressively towards them."]

function behaviorFormatter(i) {
	i = overviewResearchLink[i];
	allEvos = getAllIndexes(overviewResearchLink, i);
	allSpecial = [];
	for (as = 0; as < specialPkmnNum.length; as ++) {
		if (allEvos.includes(specialPkmnNum[as]) && ((as >= 50 && as < 90) || (as >= 125 && as < 150))) {
			allSpecial.push(as);
		}
	}

  var outputString = "";
	outputString = behaviorFormatterSwitch(outputString, "normal", allEvos);
	if (allSpecial.length > 0) {
		outputString = behaviorFormatterSwitch(outputString, "special", allSpecial);
	}

	outputString = outputString.substring(0,outputString.length-2);
	return outputString;
}

function behaviorFormatterSwitch(outputString, listType, list) {
	if (listType == "special") {
		tempUsed = specialPkmnTemperament;
		dispUsed = specialPkmnDisposition;
		respUsed = specialPkmnResponse;
		var nameUsed = specialPkmn;
		var listUsed = allSpecial;
	}
	else {
		tempUsed = overviewTemperament;
		dispUsed = overviewDisposition;
		respUsed = overviewResponse;
		var nameUsed = overviewName;
		var listUsed = allEvos;
	}
	for (intA = 0; intA < listUsed.length; intA++) {
		a = listUsed[intA];
		var tmpTemp = parseInt(tempUsed[a]);
		var tmpDisp = parseInt(dispUsed[a]);
		var tmpResp = parseInt(respUsed[a]);
    var behaviorNum = -1;
	  switch(true) {
		  case ((tmpTemp < 0) && (tmpDisp < 0)):
				behaviorNum = 0;
				break;
			case ((tmpTemp < 0) && (tmpDisp == 0)):
				behaviorNum = 1;
				break;
			case ((tmpTemp < 0) && (tmpDisp > 0)):
				behaviorNum = 2;
				break;
			case ((tmpTemp == 0) && (tmpDisp < 0)):
				behaviorNum = 3;
				break;
			case ((tmpTemp == 0) && (tmpDisp == 0)):
				behaviorNum = 4;
				break;
			case ((tmpTemp == 0) && (tmpDisp > 0)):
		  	behaviorNum = 5;
		  	break;
			case ((tmpTemp > 0) && (tmpDisp < 0)):
				behaviorNum = 6;
				break;
			case ((tmpTemp > 0) && (tmpDisp == 0)):
				behaviorNum = 7;
				break;
			case ((tmpTemp > 0) && (tmpDisp > 0)):
			  behaviorNum = 8;
				break;
			}
			var tmpString="<b>" + nameUsed[a] +"</b> are <b>" + behaviorType[behaviorNum] + "</b> Pokémon. " + behaviorString[behaviorNum];
			var responseString = "";
			if (tmpResp != 0) {
				var responseString1 = "";
				var responseString2 = "";
				if (Math.abs(tmpResp) == 1) {
					responseString1 = "tend to";
				}
				else {
					responseString1 = "almost always"
				}
				if (tmpResp < 0) {
					responseString2 = "flee";
				}
				else {
					responseString2 = "fight"
				}
				responseString = " They " + responseString1 + " " + responseString2 + " when they sense danger."
			}
			else {
				responseString = " They may either fight or flee when they sense danger.";
			}
			outputString = outputString +  tmpString + responseString + " <font size=2><a href='../About/BehaviorAbout.html'>(" + tmpTemp + " / " + tmpDisp + " / " + tmpResp + ")</a></font><br><br>";
		}
		return(outputString);
	}

	function etymologyFormatter(i) {
		var outputString = "";

		outputString = outputString + '<i>' + overviewSN[i].split(" ")[0] + '</i> ' + etymology1[i] + " <i>" + overviewSN[i].split(" ")[1] + '</i> ' + etymology2[i];
		if (overviewSN[i].split(" ").length < 2) {
			outputString = "";
		}
		return outputString;
	}

