function colorStyleSetter(col) {
	bgCol = col[0];
	var bgCol = bgCol.substring(bgCol.indexOf('(') +1, bgCol.length -1).split(', ');
	if ((bgCol[0] < 100 && bgCol[1] < 100) || (bgCol[0] < 100 && bgCol[2] < 100) || (bgCol[1] < 100 && bgCol[2] < 100)) {
		var block = document.getElementsByTagName("p");
		for (var i = 0; i < block.length; i++) {
			block[i].setAttribute("style","color:#f0f0f0 !important");
		}
		var block = document.getElementsByTagName("h3");
		for (var i = 0; i < block.length; i++) {
			block[i].setAttribute("style","color:#fff !important");
		}
	}
	document.documentElement.style.backgroundColor = "rgb" + col[0];
	document.getElementById("navbar").style.backgroundColor = "rgb" + col[1];
	document.getElementById("navbar").style.borderColor = "rgb" + col[3];
	if (document.getElementById("entryImage") != null) {
		document.getElementById("entryImage").style.backgroundColor = "rgb" + col[4];
		document.getElementById("entryImage").style.borderColor = "rgb" + col[3];
	}
	var block = document.getElementsByTagName("a");
	for (var i = 0; i < block.length; i++) {
		block[i].setAttribute("style","color:rgb" + col[2] + " !important");
	}

	var block = document.getElementsByTagName("hr");
	for (var i = 0; i < block.length; i++) {
		block[i].setAttribute("style","border-top:1px solid rgb" + col[4] + " !important");
	}

	var block = document.getElementsByClassName("w3-button w3-dark-grey");
	for (var i = 0; i < block.length; i++) {
		block[i].setAttribute("style","background-color:rgb" + col[1] + " !important");
	}

	var block = document.getElementsByClassName("wsite-button");
	for (var i = 0; i < block.length; i++) {
		block[i].setAttribute("style","color:rgb" + col[2] + " !important");
	}

}

